import { normalize, rank, type IndexRow } from './chordIndex';
import type { Song } from './types';

/**
 * Built-in Hebrew library ("ספר האקורדים הישראלי", Oren Mustaki), generated by
 * tools/hebrew_library/build_hebrew.py into public/he/. Nothing is loaded
 * until the user searches or opens the Hebrew browse section.
 */
export interface HeManifest {
  version: string;
  songs: number;
  artists: number;
  perShard: number;
  source: string;
  credit: string;
  license: string;
}

/** [num, title, artist, key, page] */
export type HeRow = [number, string, string, string, number];

interface HeBody {
  p: string[];
  s: [string, number][];
  k: string;
}

const BASE = `${import.meta.env.BASE_URL}he/`;
let manifestP: Promise<HeManifest | null> | null = null;
let indexP: Promise<HeRow[]> | null = null;
const shards = new Map<number, Promise<HeBody[] | null>>();

async function getJson<T>(url: string): Promise<T | null> {
  const r = await fetch(url);
  if (!r.ok || !(r.headers.get('content-type') ?? '').includes('json')) return null;
  return (await r.json()) as T;
}

export function loadHeManifest(): Promise<HeManifest | null> {
  manifestP ??= getJson<HeManifest>(`${BASE}manifest.json`).catch(() => null);
  return manifestP;
}

export function loadHeIndex(): Promise<HeRow[]> {
  indexP ??= loadHeManifest().then(async (m) => {
    if (!m) return [];
    return (await getJson<HeRow[]>(`${BASE}index.json?v=${m.version}`)) ?? [];
  });
  // Allow a retry after a failed (e.g. offline) first load.
  indexP.then((rows) => {
    if (!rows.length) indexP = null;
  });
  return indexP;
}

export const heSongId = (row: HeRow): string => `he-${row[4]}`;

/** Same matching and ranking as the dataset search (word prefixes on title + artist). */
export function searchHe(rows: HeRow[], query: string, limit = 60): HeRow[] {
  if (normalize(query).length < 2) return [];
  const byNum = new Map(rows.map((r) => [r[0], r]));
  return rank(rows.map((r) => [r[0], r[1], r[2], r[3]] as IndexRow), query)
    .slice(0, limit)
    .map((r) => byNum.get(r[0])!);
}

/** Each comma-separated performer gets the song ("מתי כספי, שלמה גרוניך"). */
export function performers(artist: string): string[] {
  return artist
    .split(',')
    .map((a) => a.trim())
    .filter(Boolean);
}

export interface HeArtist {
  name: string;
  rows: HeRow[];
}

export function groupArtists(rows: HeRow[]): HeArtist[] {
  const map = new Map<string, HeRow[]>();
  for (const r of rows) {
    for (const a of performers(r[2])) {
      if (!map.has(a)) map.set(a, []);
      map.get(a)!.push(r);
    }
  }
  return [...map].map(([name, rs]) => ({ name, rows: rs.sort((x, y) => x[1].localeCompare(y[1], 'he')) }));
}

/** Browse letter: first Hebrew letter (final forms folded), else '#'. */
export function heLetter(name: string): string {
  const ch = normalize(name).charAt(0);
  const finals: Record<string, string> = { 'ך': 'כ', 'ם': 'מ', 'ן': 'נ', 'ף': 'פ', 'ץ': 'צ' };
  if (ch >= 'א' && ch <= 'ת') return finals[ch] ?? ch;
  return '#';
}

export function bodyToHeSong(row: HeRow, body: HeBody, m: Pick<HeManifest, 'source'>): Song {
  return {
    id: heSongId(row),
    title: row[1],
    artist: row[2],
    key: body.k || row[3],
    tempo: 100,
    source: 'hebrew-book',
    sections: body.s
      .map(([name, idx]) => ({
        name,
        chords: (body.p[idx] ?? '')
          .split(' ')
          .filter(Boolean)
          .map((chord) => ({ chord, beats: 4 })),
      }))
      .filter((s) => s.chords.length),
    genre: `${m.source}, עמ' ${row[4]}`,
  };
}

export async function loadHeSong(row: HeRow): Promise<Song | null> {
  const m = await loadHeManifest();
  if (!m) return null;
  const n = Math.floor(row[0] / m.perShard);
  let p = shards.get(n);
  if (!p) {
    p = getJson<HeBody[]>(`${BASE}s/${n}.json?v=${m.version}`).catch(() => null);
    shards.set(n, p);
    p.then((b) => !b && shards.delete(n));
  }
  const bodies = await p;
  const body = bodies?.[row[0] % m.perShard];
  return body ? bodyToHeSong(row, body, m) : null;
}
